import {createEcologyCore} from './simulation/ranch-ecology-core.mjs';
import {wetWeather,stormNear} from './simulation/weather-state.mjs';
import * as T from 'three';
import {hash} from './town-life/people/core.mjs';
export {renewAnimal} from './ranch-ecology-state.mjs?v=2';
export function createEcology(root,places,heightAt,seed){
 let model=createEcologyCore(places,seed),externalModel=false;
 const parent=root;root=new T.Group();root.name="Ecology presentation";parent.add(root);
 const patches=places.filter(p=>p.species).map(p=>{const mat=new T.MeshStandardMaterial({color:'#95a850',roughness:1,transparent:true,opacity:.32});const mesh=new T.Mesh(new T.CircleGeometry(Math.min(p.w,p.d)*.32,12),mat);mesh.rotation.x=-Math.PI/2;mesh.position.set(p.world.x,heightAt(p.world.x,p.world.z)+.025,p.world.z);root.add(mesh);return {id:p.id,cover:1,mesh};});
 const anchors=places.filter(p=>p.role==='field'),visitors=[];
 const geo=new T.SphereGeometry(.06,4,3),mat=new T.MeshBasicMaterial({color:'#e9bd53'});
 for(let i=0;i<Math.min(12,anchors.length*4);i++){const body=new T.Mesh(geo,mat);root.add(body);visitors.push({body,anchor:anchors[i%anchors.length],phase:hash(seed+':pollinator:'+i)%100});}
 const puddles=anchors.slice(0,6).map(p=>{const material=new T.MeshStandardMaterial({color:'#738f9c',transparent:true,opacity:.4,roughness:.15});const mesh=new T.Mesh(new T.CircleGeometry(.7,12),material);mesh.rotation.x=-Math.PI/2;mesh.position.set(p.entry.x,heightAt(p.entry.x,p.entry.z)+.03,p.entry.z);root.add(mesh);return mesh;});
 const blooms=[];const bloomGeo=new T.SphereGeometry(.12,5,4),bloomMat=new T.MeshStandardMaterial({color:'#d9a1a3',roughness:1});
 for(const anchor of anchors)for(let i=0;i<8;i++){const mesh=new T.Mesh(bloomGeo,bloomMat),x=anchor.world.x+(i%4-1.5)*.5,z=anchor.world.z+(Math.floor(i/4)-.5)*.5;mesh.position.set(x,heightAt(x,z)+.2,z);mesh.userData.pickupStableId='plant:'+anchor.plan.id+':'+anchor.id+':'+i;root.add(mesh);blooms.push({mesh,slot:'plant:'+anchor.plan.id+':'+anchor.id+':'+i,seed:hash(seed+anchor.id+i)%100/100});}
 const traceGeo=new T.CircleGeometry(.13,5),traceMat=new T.MeshBasicMaterial({color:'#675c48',transparent:true,opacity:.3,depthWrite:false});const traces=new T.InstancedMesh(traceGeo,traceMat,96);traces.count=0;root.add(traces);const marker=new T.Object3D(),lastSteps=new Map();let traceIndex=0,lastTrace=0;
 let time=0,traceTime=0;return {useModel(next){model=next;externalModel=true;},setPresentationHidden(hidden){root.visible=!hidden;},update(dt,state,workers=[],animationDt=dt/6){if(!externalModel)model.step(dt,state);time+=animationDt;traceTime+=dt;if(traceTime-lastTrace>1){lastTrace=traceTime;const ids=new Set(workers.map(w=>w.person.id));for(const id of lastSteps.keys())if(!ids.has(id))lastSteps.delete(id);for(const w of workers){if(!w.body.visible)continue;const prev=lastSteps.get(w.person.id);if(!prev||Math.hypot(prev.x-w.position.x,prev.z-w.position.z)>.9){lastSteps.set(w.person.id,{...w.position});marker.position.set(w.position.x,heightAt(w.position.x,w.position.z)+.025,w.position.z);marker.rotation.set(-Math.PI/2,0,w.body.rotation.y);marker.updateMatrix();traces.setMatrixAt(traceIndex++%96,marker.matrix);traces.count=Math.min(96,traceIndex);traces.instanceMatrix.needsUpdate=true;}}}for(let i=0;i<blooms.length;i++){const b=blooms[i],data=model.blooms[i],individual=data.individual;if(!individual)continue;b.mesh.userData.storyId=individual.id;b.mesh.userData.inspect={title:'Meadow flower',kind:'Individual plant',description:'An annual that seeds a successor near its original spot.'};b.mesh.userData.liveReadout=()=>`${data.stage} · generation ${individual.generation} · bloom size ${individual.traits.bloom} · ${individual.id}`;b.mesh.scale.setScalar(data.scale);b.mesh.visible=data.visible;}for(let i=0;i<patches.length;i++){const patch=patches[i];patch.cover=model.patches[i].cover;patch.mesh.material.color.set('#b7a077').lerp(new T.Color('#839d45'),patch.cover);}

 for(const v of visitors){v.body.visible=state.season?.index!==3&&!wetWeather(state.weather)&&!stormNear(state.weatherFront)&&(state.calendar?.hour??12)>6&&(state.calendar?.hour??12)<19;const t=time*.35+v.phase;v.body.position.set(v.anchor.world.x+Math.cos(t)*2,heightAt(v.anchor.world.x,v.anchor.world.z)+.5+Math.sin(t*2)*.2,v.anchor.world.z+Math.sin(t*.7)*2);}
 for(const p of puddles)p.visible=wetWeather(state.weather);
 },snapshot:()=>model.snapshot(),restore(saved){model.restore(saved);},dispose(){parent.remove(root);lastSteps.clear();root.remove(traces);traceGeo.dispose();traceMat.dispose();for(const b of blooms)root.remove(b.mesh);bloomGeo.dispose();bloomMat.dispose();for(const p of [...patches.map(p=>p.mesh),...puddles]){root.remove(p);p.geometry.dispose();p.material.dispose();}for(const v of visitors)root.remove(v.body);geo.dispose();mat.dispose();}};
}
